 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 private void sendSettings(){if(RadarService.running)startService(new Intent(this,RadarService.class).setAction("SETTINGS"));}
 private final Runnable refresh=new Runnable(){public void run(){refreshMonitor();phone.setText("手機｜"+RadarService.status);phone.setTextColor(RadarService.status.contains("中斷")?Ui.RED:RadarService.running?Ui.MINT:Ui.MUTED);feed.setText("行情｜"+RadarService.feed);feed.setTextColor(RadarService.feed.contains("正常")?Ui.MINT:RadarService.feed.contains("中斷")?Ui.RED:Ui.MUTED);error.setText(RadarService.error);activity.setText(RadarService.activityText.isEmpty()?"等待資料":RadarService.activityText);start.setText(RadarService.running?"停止雷達":"啟動雷達");scanLabel.setText(p.getBoolean("demo",true)?"● 模擬環境｜不是真實行情":"● 正式模式｜需後端及行情授權");if(!last.equals(RadarService.lastSignal)){last=RadarService.lastSignal;try{JSONObject j=new JSONObject(last);StringBuilder b=new StringBuilder((j.optBoolean("demo")?"【模擬】":"")+j.optString("symbol")+" "+j.optString("name")+"｜轉弱確認  "+j.optInt("hits")+"/5\n現價 "+Ui.num(j,"price")+"  VWAP "+Ui.num(j,"vwap")+"\n");JSONArray c=j.optJSONArray("conditions");for(int k=0;k<5;k++)b.append(c==null||c.isNull(k)?"？":c.optBoolean(k)?"✓":"×").append(" C").append(k+1).append(" ").append(Ui.LABELS[k]).append("\n");b.append("訊號來源：").append(RadarService.sourceName(j.optString("source"))).append("\n先賣後買：").append(Ui.yes(j,"daytrade")).append("\n平盤下融券：").append(Ui.yes(j,"below_flat")).append("\n券源：").append(Ui.borrow(j)).append("\n防守 A：").append(Ui.num(j,"stop_a")).append("   B：").append(Ui.num(j,"stop_b")).append("\n資格來源：").append(j.optString("qualification_source","未知"));signal.setText(b.toString());signal.setTextColor(Ui.FG);latency.setText(RadarService.latency>=0?"後端收包至手機接收時間差（需時鐘同步）："+RadarService.latency+" ms":"端到端時間差：未測");}catch(Exception ignored){}}h.postDelayed(this,700);}};
 private String elapsed(long ms){long z=Math.max(0,ms/1000);return String.format(Locale.TAIWAN,"%02d:%02d:%02d",z/3600,(z/60)%60,z%60);}
 private String age(long t,long n){return t<=0?"未收到":Math.max(0,(n-t)/1000)+" 秒前";}
 private String timestamp(long t){if(t<=0)return "未回報";return java.time.Instant.ofEpochMilli(t).atZone(java.time.ZoneId.of("Asia/Taipei")).format(java.time.format.DateTimeFormatter.ofPattern("MM/dd HH:mm:ss.SSS"));}
 private void refreshMonitor(){MonitorState x=RadarService.MON;long n=SystemClock.elapsedRealtime();boolean live=RadarService.running,configured=p.getString("url","").startsWith("wss://"),fresh=x.engineFresh(n);String state=x.state(n,live,RadarService.marketWindow(),configured);monitorState.setText("● "+state);monitorState.setTextColor(state.equals("收到策略運算回報")?Ui.MINT:state.contains("中斷")||state.contains("重連")?Ui.RED:Ui.GOLD);
 monitorNumbers.setText("背景服務："+(live?"已啟動":"已停止")+"｜本機服務最後巡檢："+age(x.tick,n)+"\n連續運作："+(live?elapsed(n-x.start):"—")+"\n已訂閱："+(x.count<0||!live||!x.socket?"未回報":x.count+" / "+(x.expected<0?"—":x.expected))+"\n本次收到後端封包："+x.packets+" 筆（含心跳、狀態）\n後端最後封包："+age(x.packet,n)+"\n今日策略運算："+(fresh?x.evaluations+" 次":"未回報／逾時")+"\n每秒實際成交接收："+(fresh?x.quoteRate+" 筆":"未回報／逾時")+"\n最後成交："+(fresh?timestamp(x.lastQuote):"未回報")+"\n最後策略運算："+(fresh?timestamp(x.lastEval):"未回報")+"\n正式訊號接收："+x.signals+"｜模擬："+x.demoSignals+"\n重連次數："+x.reconnects+"\n語音引擎："+(x.tts?"就緒":"未就緒")+"｜CPU 喚醒鎖："+(x.wake?"持有":"未持有"));
 monitorFlow.setText(x.events.isEmpty()?"尚無紀錄":android.text.TextUtils.join("\n",x.events));}
 private void selfCheck(){MonitorState x=RadarService.MON;android.net.ConnectivityManager cm=(android.net.ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);android.net.NetworkCapabilities nc=cm==null?null:cm.getNetworkCapabilities(cm.getActiveNetwork());PowerManager pm=getSystemService(PowerManager.class);boolean noti=getSystemService(NotificationManager.class).areNotificationsEnabled();String result="網路驗證："+(nc!=null&&nc.hasCapability(android.net.NetworkCapabilities.NET_CAPABILITY_VALIDATED)?"通過":"未驗證")+"\n背景服務："+(RadarService.running?"已啟動":"未啟動")+"\n行情後端："+(x.socket?"已連線":"未連線")+"\n策略運算："+(x.engineFresh(SystemClock.elapsedRealtime())?"已收到統計":"未驗證")+"\n懸浮視窗權限："+(Settings.canDrawOverlays(this)?"已授權":"未授權")+"\n通知權限："+(noti?"已開啟":"未開啟")+"\n電池最佳化："+(pm.isIgnoringBatteryOptimizations(getPackageName())?"已排除":"仍受限制")+"\n中文語音："+(x.tts?"引擎已就緒":"未就緒")+"\n此檢查不等於真機鎖屏測試或實盤驗收。";
 new AlertDialog.Builder(this).setTitle("系統自檢").setMessage(result).setPositiveButton("關閉",null).show();}
 private EditText field(LinearLayout l,String label,String value,boolean number){l.addView(Ui.text(this,label,13,Ui.MUTED,true));EditText e=new EditText(this);e.setTextColor(Ui.FG);e.setTextSize(15);e.setText(value);e.setSingleLine(true);if(number)e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);l.addView(e);return e;}
 private Switch toggle(LinearLayout l,String key,String name,boolean def){Switch s=new Switch(this);s.setText(name);s.setTextColor(Ui.FG);s.setChecked(p.getBoolean(key,def));l.addView(s);return s;}
 private void settings(){ScrollView sc=new ScrollView(this);LinearLayout l=Ui.col(this);l.setPadding(24,10,24,10);sc.addView(l);Switch demo=toggle(l,"demo","本機模擬（關閉後使用正式後端）",true);EditText url=field(l,"後端 WSS 網址",p.getString("url",""),false);EditText token=field(l,"後端存取 Token（非券商金鑰）",p.getString("token",""),false);token.setInputType(129);l.addView(Ui.text(this,"行情來源、金鑰及憑證在後端設定；手機不接收券商登入資料。",12,Ui.MUTED,false));EditText watch=field(l,"自選股（逗號分隔，最多100檔）",p.getString("watch","2454,2330,2327,3037,3711"),false);String[] keys={"hits","volume_multiple","relative_seconds","idle_seconds","min_avg_lots","min_price","max_price","top","cooldown","vwap_buffer","break_seconds","descending_bars"};String[] labels={"命中條件數 N (1–5)","爆量倍數","相對弱勢秒數","無新成交秒數","前5日平均張數","最低股價","最高股價","全市場金額排名","訊號冷卻秒數","VWAP 緩衝比例 (0.003=0.3%)","破底窗口秒數","下降K棒根數"};String[] defaults={"5","1.5","180","60","1000","15","1500","150","300","0.003","300","3"};JSONObject c;try{c=new JSONObject(p.getString("config","{}"));}catch(Exception e){c=new JSONObject();}EditText[] edits=new EditText[keys.length];for(int i=0;i<keys.length;i++)edits[i]=field(l,labels[i],c.optString(keys[i],defaults[i]),true);Switch voice=toggle(l,"voice","語音播報",true),nameVoice=toggle(l,"nameVoice","念中文股名",true),vibrate=toggle(l,"vibrate","雙短震動",true),floatSwitch=toggle(l,"overlay","顯示浮窗",true);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("雷達設定").setView(sc).setNegativeButton("取消",null).setPositiveButton("儲存",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{JSONObject out=new JSONObject();for(int i=0;i<keys.length;i++){double value=Double.parseDouble(edits[i].getText().toString());if(value<0)throw new Exception();if(i==1||i==5||i==6||i==9)out.put(keys[i],value);else {if(value!=(int)value)throw new Exception();out.put(keys[i],(int)value);}}if(out.getInt("hits")<1||out.getInt("hits")>5||out.getDouble("min_price")>out.getDouble("max_price"))throw new Exception();String w=watch.getText().toString().trim();if(!w.matches("[0-9,，\\s]*"))throw new Exception();boolean restart=RadarService.running&&(demo.isChecked()!=p.getBoolean("demo",true)||!url.getText().toString().equals(p.getString("url",""))||!token.getText().toString().equals(p.getString("token","")));p.edit().putBoolean("demo",demo.isChecked()).putString("url",url.getText().toString()).putString("token",token.getText().toString()).putString("watch",w).putString("config",out.toString()).putBoolean("voice",voice.isChecked()).putBoolean("nameVoice",nameVoice.isChecked()).putBoolean("vibrate",vibrate.isChecked()).putBoolean("overlay",floatSwitch.isChecked()).apply();if(restart){stopService(new Intent(this,RadarService.class));toast("設定已儲存，請重新啟動雷達");}else sendSettings();dialog.dismiss();}catch(Exception e){toast("請檢查數字與自選股格式");}}));dialog.show();}
 private void loadStats(){if(p.getBoolean("demo",true)){stats.setText("模擬模式不計入正式勝率");return;}String url=p.getString("url","");if(!url.startsWith("wss://")){toast("請設定後端");return;}try{String base=url.replaceFirst("^wss://","https://").replaceFirst("/ws/?$","");http.newCall(new Request.Builder().url(base+"/stats").header("Authorization","Bearer "+p.getString("token","")).build()).enqueue(new Callback(){public void onFailure(Call c,java.io.IOException e){runOnUiThread(()->stats.setText("後端統計無法取得"));}public void onResponse(Call c,Response r)throws java.io.IOException{try(Response rr=r){JSONObject j=new JSONObject(rr.body().string());StringBuilder b=new StringBuilder();String[] ks={"p5","p15","pc"},ls={"5分鐘","15分鐘","收盤"};for(int i=0;i<3;i++){JSONObject x=j.getJSONObject(ks[i]);b.append(ls[i]).append("  ").append(x.isNull("rate")?"—":x.optDouble("rate")+"%").append("（樣本 ").append(x.optInt("samples")).append("）\n");}runOnUiThread(()->stats.setText(b.toString()));}catch(Exception e){runOnUiThread(()->stats.setText("統計格式異常"));}}});}catch(Exception e){toast("網址無效");}}
 @Override protected void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}
